#!/bin/sh
# Regenerates src/Generated from spec/api.json with the pinned Kiota image. Never edit src/Generated by hand.
set -eu
root=$(cd "$(dirname "$0")/.." && pwd)
image="mcr.microsoft.com/openapi/kiota@sha256:ec6d326a8f98a067106729903928535906044aa1a42dbd1825c384080da76b13"
rm -rf "$root/src/Generated"
docker run --rm -u "$(id -u):$(id -g)" -v "$root:/w" "$image" generate \
  -l PHP -d /w/spec/api.json -o /w/src/Generated -n 'Puntjes\Generated' -c PuntjesClient \
  --serializer 'Microsoft\Kiota\Serialization\Json\JsonSerializationWriterFactory' \
  --serializer 'Microsoft\Kiota\Serialization\Text\TextSerializationWriterFactory' \
  --deserializer 'Microsoft\Kiota\Serialization\Json\JsonParseNodeFactory' \
  --deserializer 'Microsoft\Kiota\Serialization\Text\TextParseNodeFactory' \
  --clean-output --log-level Warning
# Kiota 1.35 writes @QueryParameter("snake_name") without importing the class.
grep -rl '@QueryParameter' "$root/src/Generated" | while read -r file; do
  grep -q '^use Microsoft\\Kiota\\Abstractions\\QueryParameter;' "$file" ||
    sed -i '0,/^namespace .*;$/s//&\n\nuse Microsoft\\Kiota\\Abstractions\\QueryParameter;/' "$file"
done
rm -f "$root/src/Generated/kiota-lock.json"
